import { sandboxProxy, PREFIX } from './sandbox-proxy.js'
// Pages removed in the 2026-11 pruning, mapped to their final destination
// (generated by scripts/generate-retired-redirects.mjs). Per-model API
// references moved to the main site's /models/{id}/docs and /apis/{id}/docs.
import RETIRED_REDIRECTS from './retired-redirects.json' with { type: 'json' }

const DOCS_PREFIX = '/docs'
// Longest first, so the most specific section wins.
const RETIRED_PREFIXES = Object.keys(RETIRED_REDIRECTS)
  .filter((key) => key.endsWith('/*'))
  .map((key) => key.slice(0, -1))
  .sort((a, b) => b.length - a.length)

/** Final URL for a removed page, matching with or without `.html` and a trailing slash. */
export function retiredRedirect(pathname) {
  let path = pathname
  try { path = decodeURI(pathname) } catch { /* keep the raw path */ }
  path = path.replace(/\.html$/, '')
  const trimmed = path.replace(/\/+$/, '')
  for (const candidate of [path, trimmed, `${trimmed}/`, path.replace(/\/index$/, '/')]) {
    const target = RETIRED_REDIRECTS[candidate]
    if (target) return target
  }
  // Section rules (`/docs/store/*`) catch sub-pages that never had their own entry.
  for (const prefix of RETIRED_PREFIXES) {
    if (trimmed.startsWith(prefix)) return RETIRED_REDIRECTS[`${prefix}*`]
  }
  return null
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url)

    if (url.pathname.startsWith(PREFIX + "/")) return sandboxProxy(request)

    if (url.pathname === DOCS_PREFIX) {
      url.pathname = `${DOCS_PREFIX}/`
      return Response.redirect(url, 308)
    }

    if (!url.pathname.startsWith(`${DOCS_PREFIX}/`)) {
      return new Response('Not Found', { status: 404 })
    }

    const retired = retiredRedirect(url.pathname)
    if (retired) return Response.redirect(retired, 301)

    // The former origin permanently redirected /docs/ to /docs/index. Some
    // browsers still cache that redirect, so serve the homepage internally
    // instead of redirecting /docs/index back to /docs/ and creating a loop.
    url.pathname = url.pathname === `${DOCS_PREFIX}/index`
      ? '/'
      : url.pathname.slice(DOCS_PREFIX.length) || '/'

    const response = await env.ASSETS.fetch(new Request(url, request))

    // Static asset clean-URL redirects are generated against the stripped
    // pathname (for example `/models/supported`). Re-attach the docs mount
    // point so trailing-slash links never escape to the main site and 404.
    // They are permanent canonicalisation (/page.html -> /page, /dir/index ->
    // /dir/), but the asset layer answers 307, which kept the old spellings
    // indexed; answer 301 instead.
    const location = response.headers.get('Location')
    const assetRedirect = response.status === 307 || response.status === 308
    if (location?.startsWith('/') && (assetRedirect || !location.startsWith(`${DOCS_PREFIX}/`))) {
      const headers = new Headers(response.headers)
      headers.set('Location', location.startsWith(`${DOCS_PREFIX}/`) ? location : `${DOCS_PREFIX}${location}`)
      return new Response(response.body, {
        status: assetRedirect ? 301 : response.status,
        headers,
      })
    }

    return response
  },
}
